{
  "prose": [
    {
      "key": "headline",
      "text": "Trade persona fidelity for serving cost: {arm:f64} cuts cost but regresses on consistency."
    },
    {
      "key": "lede",
      "text": "{arm:f64} saves cost over {arm:prod} while maintaining guardrails, but drops {contrast.f64.persona.delta|abs|pts} points on persona adherence. The choice turns on whether degradation in extended multi-turn dialogue is acceptable."
    },
    {
      "key": "flag.title",
      "text": "No target margin declared"
    },
    {
      "key": "flag.text",
      "text": "Because no explicit loss threshold was set in advance, the tradeoff between cost savings and persona drift requires product leadership judgment."
    },
    {
      "key": "decision.the_trade",
      "text": "{arm:f64} reduces cost from {cost_per_1k.prod|usd_per_1k} to {cost_per_1k.f64|usd_per_1k}, but persona adherence falls by {contrast.f64.persona.delta|abs|pts} points ({contrast.f64.persona.interval|interval})."
    },
    {
      "key": "decision.where_it_flips",
      "text": "The switch flips to {arm:prod} if persona degradation greater than five points is unacceptable, or if conversations routinely exceed five turns."
    },
    {
      "key": "decision.our_lean",
      "text": "Lean toward {arm:f64} if monthly serving budget is the primary constraint and prompt guardrails prevent major policy regressions."
    },
    {
      "key": "decision.what_settles_it",
      "text": "A human side-by-side trial on long sessions or an explicit minimum acceptable persona fidelity threshold will settle the choice."
    },
    {
      "key": "summary.0.title",
      "text": "Persona adherence contrast vs {arm:prod}"
    },
    {
      "key": "summary.1.title",
      "text": "Cost per 1k replies across arms"
    },
    {
      "key": "sections.contrasts_overview.eyebrow",
      "text": "Primary judged contrast"
    },
    {
      "key": "sections.contrasts_overview.headline",
      "text": "All candidates regress on persona adherence relative to {arm:prod}."
    },
    {
      "key": "sections.contrasts_overview.takeaway",
      "text": "{arm:f64} drops {contrast.f64.persona.delta|abs|pts} points ({contrast.f64.persona.interval|interval}), while {arm:cor} shows smaller loss but breaches policy guardrails."
    },
    {
      "key": "sections.contrasts_overview.title",
      "text": ""
    },
    {
      "key": "sections.contrasts_overview.caption",
      "text": "Intervals are 95% paired differences without multi-candidate correction."
    },
    {
      "key": "sections.depth_trajectory.eyebrow",
      "text": "Turn depth breakdown"
    },
    {
      "key": "sections.depth_trajectory.headline",
      "text": "Persona fidelity degrades steeply at deeper turns for Flash models."
    },
    {
      "key": "sections.depth_trajectory.takeaway",
      "text": "While {arm:f64} is competitive in turns one and two, its adherence falls sharply past five turns."
    },
    {
      "key": "sections.depth_trajectory.title",
      "text": ""
    },
    {
      "key": "sections.depth_trajectory.caption",
      "text": "Strata differences are descriptive and uncorrected."
    },
    {
      "key": "sections.scenario_breakdown.eyebrow",
      "text": "Behavioral scenarios"
    },
    {
      "key": "sections.scenario_breakdown.headline",
      "text": "Drift is concentrated in banter and corrections."
    },
    {
      "key": "sections.scenario_breakdown.takeaway",
      "text": "{arm:f64} holds persona well during song intros but struggles when receiving corrections or in banter."
    },
    {
      "key": "sections.scenario_breakdown.title",
      "text": ""
    },
    {
      "key": "sections.scenario_breakdown.caption",
      "text": "Delta relative to control per scenario; uncorrected descriptive figures."
    },
    {
      "key": "durable_claims.0",
      "text": "{arm:prod} achieves {judged.persona.prod|pct} persona adherence, exceeding {arm:f64} at {judged.persona.f64|pct} by {contrast.f64.persona.delta|abs|pts} points ({contrast.f64.persona.interval|interval})."
    },
    {
      "key": "durable_claims.1",
      "text": "{arm:f64} costs {cost_per_1k.f64|usd_per_1k} and {arm:f16} costs {cost_per_1k.f16|usd_per_1k}, compared to {cost_per_1k.prod|usd_per_1k} for {arm:prod}."
    },
    {
      "key": "durable_claims.2",
      "text": "{arm:cor} fails the speculation guardrail at {measure.specul.cor.mean|pct}, down {contrast.cor.specul.delta|abs|pts} points ({contrast.cor.specul.interval|interval}) relative to {arm:prod}."
    },
    {
      "key": "method.0.term",
      "text": "Sample and repeats"
    },
    {
      "key": "method.0.text",
      "text": "The evaluation ran {scoreboard.prod.cases} distinct dialogue cases across {scoreboard.prod.ran} total trials."
    },
    {
      "key": "method.1.term",
      "text": "Persona evaluation"
    },
    {
      "key": "method.1.text",
      "text": "Graded by a calibrated judge rubric ({judge.agreement|pct} agreement on {judged.persona.calibration_ratings} human comparisons)."
    },
    {
      "key": "method.2.term",
      "text": "Guardrails"
    },
    {
      "key": "method.2.text",
      "text": "Requires music facts above 90% and non-speculation adherence above 95% on prompt bait tests."
    },
    {
      "key": "method.3.term",
      "text": "Interval estimation"
    },
    {
      "key": "method.3.text",
      "text": "Reported intervals reflect {family.level} confidence on paired differences with {family.correction} family correction."
    },
    {
      "key": "method.4.term",
      "text": "Cost calculation"
    },
    {
      "key": "method.4.text",
      "text": "Token usage priced per thousand replies across varying context lengths over conversation turns."
    },
    {
      "key": "explore.title",
      "text": "Explore tradeoff parameters"
    },
    {
      "key": "explore.recomputes",
      "text": "Adjusting valuation per persona point re-ranks {arm:prod} and {arm:f64}."
    },
    {
      "key": "explore.controls.price_sensitivity.title",
      "text": "Valuation per persona point ($)"
    }
  ]
}

